import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"剝","description":"焦氏易林注 - 剝","frontmatter":{"title":"剝","description":"焦氏易林注 - 剝"},"headers":[],"relativePath":"classics/jiaoyilin/023.md","filePath":"classics/jiaoyilin/023.md"}'),l={name:"classics/jiaoyilin/023.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="剝" tabindex="-1">剝 <a class="header-anchor" href="#剝" aria-label="Permalink to “剝”">​</a></h1><h3 id="剝-1" tabindex="-1">剝 <a class="header-anchor" href="#剝-1" aria-label="Permalink to “剝”">​</a></h3><h3 id="剝之乾" tabindex="-1">剝之乾 <a class="header-anchor" href="#剝之乾" aria-label="Permalink to “剝之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>穿胸狗邦，僵離旁舂。天地易紀，日月更始。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《謙》。</p><h3 id="剝之坤" tabindex="-1">剝之坤 <a class="header-anchor" href="#剝之坤" aria-label="Permalink to “剝之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>從風縱火，荻芝俱死。三害集房，十子中傷。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>剝艮為火，坤為荻芝、為死、為害，艮數三，故曰三害。艮為房，坤為集，數十，故曰十子。《左傳昭十四年》：&quot;三言而除三惡，暴虐頗也&quot;，三惡即三害。《論衡》進用也，而蒙三害。《書胤徵》：&quot;辰弗集於房&quot;。</p><h3 id="剝之屯" tabindex="-1">剝之屯 <a class="header-anchor" href="#剝之屯" aria-label="Permalink to “剝之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>北山有棗，橘柚所聚。荷囊載擔，香盈筐筥。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坎北。艮為山、為棗、為橘柚，坤為聚，艮為負荷、為擔，坤為囊、為載，震為筐筥，伏巽為香。○所，宋元本作於。載擔、香盈，宋元本作載香、盈我，今依汲古本。</p><h3 id="剝之蒙" tabindex="-1">剝之蒙 <a class="header-anchor" href="#剝之蒙" aria-label="Permalink to “剝之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>齎貝贖狸，不聽我辭。繫於虎鬚，牽不得來。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《革》。 ○艮為貝證。</p><h3 id="剝之需" tabindex="-1">剝之需 <a class="header-anchor" href="#剝之需" aria-label="Permalink to “剝之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>上下惟邪，寡婦無夫。歡心隔塞，君子離居。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>惟邪，嘆息聲也。坎上下皆兌口，二至四互兌，故曰上下惟邪。離為夫，伏坤為寡，故曰寡婦，坎隱伏故無夫。坎為塞、為心、為憂，故不歡。伏艮為君子。○惟，元本作唯，依宋本、汲古。寡婦無夫，宋元本作戾其無夫，依汲古。</p><h3 id="剝之訟" tabindex="-1">剝之訟 <a class="header-anchor" href="#剝之訟" aria-label="Permalink to “剝之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>二人輦車，徙去其家。井沸釜鳴，不可安居。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>伏明夷。震為人，坤數二，坎為車，故曰二人輦車。坎為室家，震出，故徙去其家。坎為井，坤水在井上，故曰井沸。坤為釜，震鳴，故釜鳴。坎險，故不安。水經註：曲阿季子廟前井及潭皆沸。楚辭：瓦釜雷鳴。然此似另有故實，為今所不解。</p><h3 id="剝之師" tabindex="-1">剝之師 <a class="header-anchor" href="#剝之師" aria-label="Permalink to “剝之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>蹇驢不材，俊驥失時。筋力勞盡，疲於沙邱。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳履之巽。○俊，汲古作駿，筋作筋，依宋元本。宋元本三四句倒置，依汲古。</p><h3 id="剝之比" tabindex="-1">剝之比 <a class="header-anchor" href="#剝之比" aria-label="Permalink to “剝之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>明夷兆初，為穆出郊。以讒復歸，名曰豎牛。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>剝亂叔孫，餒於虛邱。坎隱伏，故曰明夷。初動，故曰兆初。坤為傷，坎上下兌口相背，故曰讒。艮為豎，坤為牛、為餒，艮為叔孫、為沙邱。《左傳昭四年》：叔孫穆子出亡，至庚宗，遇婦人，宿焉。生豎牛。及自齊歸，遂使為豎。後叔孫田於丘蕕遇疾，豎牛遂為亂，穆子餒死。又五年雲：初，叔孫穆子之生莊叔，噬之，遇明夷之謙，故曰明夷兆初。林全用此事，惟沙邱傳作丘蕕而李善《文選運命論》註引作蒲丘。據此則虛丘應作蒲丘。○郊，元本作交，依宋本、汲古。夷兆，各本作傷之，依大壯之比校。大壯之比第二句作三旦為災。餒，汲古本作飫，宋元本作喂，亦依大壯之比校。</p><h3 id="剝之小畜" tabindex="-1">剝之小畜 <a class="header-anchor" href="#剝之小畜" aria-label="Permalink to “剝之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>天火大起，飛鳥驚駭。作事不時，自為身咎。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>乾天離火，伏艮為鳥，震為驚駭，艮為時，艮伏故不時。伏坤為自、為身。○身，汲古作多，依宋元本。</p><h3 id="剝之履" tabindex="-1">剝之履 <a class="header-anchor" href="#剝之履" aria-label="Permalink to “剝之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>土與山連，共保歲寒。終無災患，萬世長安。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。坤土艮山，故曰土與山連。坤為歲，坎為寒、為災患，坤為萬、為世，艮為安。</p><h3 id="剝之泰" tabindex="-1">剝之泰 <a class="header-anchor" href="#剝之泰" aria-label="Permalink to “剝之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>日出阜東，山蔽其明。章甫薦履，箕子佯狂。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《屯》。</p><h3 id="剝之否" tabindex="-1">剝之否 <a class="header-anchor" href="#剝之否" aria-label="Permalink to “剝之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>龍馬上山，絕無水泉。喉焦唇乾，口不能言。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《訟》。</p><h3 id="剝之同人" tabindex="-1">剝之同人 <a class="header-anchor" href="#剝之同人" aria-label="Permalink to “剝之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>雄處弱水，雌在海濱。將別持食，悲哀於心。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。坤為水、為柔，故曰弱水，九二居坤中，故曰雄處弱水。《同人》乾為海，六二居海中，故曰雌在海濱。坎為心、為悲哀。○將別，宋元本作別將，依汲古。</p><h3 id="剝之大有" tabindex="-1">剝之大有 <a class="header-anchor" href="#剝之大有" aria-label="Permalink to “剝之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>庭燎夜明，追古傷今。陽弱不制，陰雄生戾。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。艮為庭、為燎、為明，坎為夜，《比》祗九五一陽故曰陽弱、曰陰雄。陳樸園雲：&quot;宣王中年怠政，而庭燎詩作，後脫簪珥諫曰：妾不才使君王宴朝，請待罪永巷，宣王悟&quot;，林曰追古傷今，指其事也。義與毛異。○第二三兩句依《頤》之《損》校，宋元、汲古本皆作&quot;追嗣日光，陽軟不至&quot;。</p><h3 id="剝之謙" tabindex="-1">剝之謙 <a class="header-anchor" href="#剝之謙" aria-label="Permalink to “剝之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>三婦同夫，忽不相思。志恆悲愁，顏色不怡。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為夫，數三，坤為婦，坤震連，故三婦同夫。坎為思、為志、為悲愁，艮為顏色，坤為惡，故相惡而不思。○悲愁，依宋元本，汲古作不愁，非。</p><h3 id="剝之豫" tabindex="-1">剝之豫 <a class="header-anchor" href="#剝之豫" aria-label="Permalink to “剝之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>鶴盜我珠，逃於東都。鵠怒追求，郭氏之墟。不見武跡，反為患災。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《明夷》。</p><h3 id="剝之隨" tabindex="-1">剝之隨 <a class="header-anchor" href="#剝之隨" aria-label="Permalink to “剝之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>獮猴冠帶，盜載非位。眾犬共吠，狂走蹶足。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為獮猴、為冠，巽為帶、為盜，震為載，艮為位。冠帶者，有位之服，今獮猴冠帶，乃盜用耳，故曰非位。艮犬震吠，正反艮故曰眾。震為狂、為走、為足，兌折故蹶足。○獮猴，汲古作沭猴，《史記項羽本紀》：&quot;如沭猴而冠耳&quot;，今依宋元本。又載汲古作在，亦依宋元本。狂走，宋元本作麏走，汲古作倉狂，今依《大壯》之《屯》校。</p><h3 id="剝之蠱" tabindex="-1">剝之蠱 <a class="header-anchor" href="#剝之蠱" aria-label="Permalink to “剝之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>黍稷禾稻，垂畝方好。中旱不雨，傷風病槁。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《蹇》。</p><h3 id="剝之臨" tabindex="-1">剝之臨 <a class="header-anchor" href="#剝之臨" aria-label="Permalink to “剝之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>雄聖伏，名人匿。麟遠走，鳳飛北。亂禍未息。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《大過》。 ○前四句句三字，第五句句四字。漢魏叢書本皆按四字斷句，非。</p><h3 id="剝之觀" tabindex="-1">剝之觀 <a class="header-anchor" href="#剝之觀" aria-label="Permalink to “剝之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>王母多福，天祿所伏。居之寵光，君子有福。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為母，伏乾故曰王母、曰福、曰天祿。巽為伏，艮為居、為光、為君子。</p><h3 id="剝之噬嗑" tabindex="-1">剝之噬嗑 <a class="header-anchor" href="#剝之噬嗑" aria-label="Permalink to “剝之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>被服文德，升入大麓。四門雍肅，登受大福。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>詳《隨》之《大壯》。離為文，互艮為山麓、為門，震卦數四，故曰四門。震為登、為福。○宋本作《復》林。</p><h3 id="剝之賁" tabindex="-1">剝之賁 <a class="header-anchor" href="#剝之賁" aria-label="Permalink to “剝之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>褰衣涉河，水深漬罷。幸賴舟子，濟脫無他。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>依《訟》之《萃》校。震為舟證。衣，宋元本、汲古皆作裳。水，宋元本作流。罷，宋元本、汲古作衣。</p><h3 id="剝之剝" tabindex="-1">剝之剝 <a class="header-anchor" href="#剝之剝" aria-label="Permalink to “剝之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>行觸大諱，與司命忤。執囚束縛，拘制於吏，幽人有喜。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤死，故曰大諱。坤惡，故曰忤。艮為官，故曰司命。《天文志》：&quot;鬥魁六星，五曰司命，主壽&quot;。艮為吏、為手，故曰執，為拘囚、為束縛、為高尚，故曰幽人。○幽，汲古作憂，依宋元本。</p><h3 id="剝之復" tabindex="-1">剝之復 <a class="header-anchor" href="#剝之復" aria-label="Permalink to “剝之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>班馬還師，以息勞疲。役夫嘉喜，入戶見妻。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《既濟》註。○宋本作《噬嗑》林。</p><h3 id="剝之無妄" tabindex="-1">剝之無妄 <a class="header-anchor" href="#剝之無妄" aria-label="Permalink to “剝之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>東鄰嫁女，為王妃後。莊公築館，以尊王母。歸於京師，季薑悅喜。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《觀》。莊當為桓。</p><h3 id="剝之大畜" tabindex="-1">剝之大畜 <a class="header-anchor" href="#剝之大畜" aria-label="Permalink to “剝之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>百足俱行，相輔為強。三聖翼事，王室寵光。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《履》。</p><h3 id="剝之頤" tabindex="-1">剝之頤 <a class="header-anchor" href="#剝之頤" aria-label="Permalink to “剝之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>危坐至暮，請求不得。膏澤不降，政戾民忒。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《離》。</p><h3 id="剝之大過" tabindex="-1">剝之大過 <a class="header-anchor" href="#剝之大過" aria-label="Permalink to “剝之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>百川朝海，泛流不止。路雖遼遠，無不到者。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>兌為海，乾亦為河海，重乾故曰百川，而海為水王，故曰朝海、故曰泛流。伏震為路，坤為遠●止，故曰到。○泛流，宋元作流行，依汲古。</p><h3 id="剝之坎" tabindex="-1">剝之坎 <a class="header-anchor" href="#剝之坎" aria-label="Permalink to “剝之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>乘騮駕驪，東至於齊。遭遇仁友，送我以資，厚得利歸。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>互震為馬、為乘、為駕、為東，伏巽為齊、為利、為資，艮為友。○齊，汲古作濟，依宋元本。</p><h3 id="剝之離" tabindex="-1">剝之離 <a class="header-anchor" href="#剝之離" aria-label="Permalink to “剝之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>禮壞樂崩，成子傲慢。欲求致理，力疲心爛。陰請不當，為簡生殃。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。坤為禮，坎陽居坤中故禮壞。震為樂，三至五震覆故樂崩。艮為成，震為子、為傲，艮為求。理，法也，欲求致理，言欲致之於法也。坎為法、為勞，故曰力疲。坎為心，離中虛，故曰心爛。震為請、為簡，坎為殃。《論語》：&quot;陳成子弒簡公，孔子沐浴而朝，請討之&quot;，林詞全指此事。○汲古第五句在第二句，六句在第四句，茲依元本，音皆諧。宋第五句作&quot;陰陽不調&quot;，多成子驕傲句，非。又陰字必有誤。</p><h3 id="剝之鹹" tabindex="-1">剝之鹹 <a class="header-anchor" href="#剝之鹹" aria-label="Permalink to “剝之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>三人輦車，乘入虎家。王母貪叨，盜我犁牛。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。震為人，數三，故曰三人。坤為車，故曰輦車。輦車，以人力行也。艮為虎、為家，艮在上，故入虎家。坤為母，對乾，故曰王母，兌食故曰貪叨。坤為牛，震為耕，故曰犁牛。犁，耕也。《鹹》互巽為盜。○三，汲古作一，依宋元本。叨，汲古作饕，依元本，義同。</p><h3 id="剝之恆" tabindex="-1">剝之恆 <a class="header-anchor" href="#剝之恆" aria-label="Permalink to “剝之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>羊頭兔足，少肉不飽。漏囊敗粟，利無所得。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>乾首兌羊，故曰羊頭。震為兔、為足，故曰兔足。坎為肉，伏坤中虛，故曰少肉、曰不飽。坤為囊，巽下斷故曰漏囊。震為粟，兌毀故敗。巽為利，兌折故無得。</p><h3 id="剝之遯" tabindex="-1">剝之遯 <a class="header-anchor" href="#剝之遯" aria-label="Permalink to “剝之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>新田宜粟，上農得谷。君子唯好，以紆百福。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>通《臨》。坤為田，《爾雅》：&quot;二歲曰新田&quot;。震為粟、為農人、為谷，本卦《艮》為君子，乾為百、為福。○唯好，汲古作懷德，紆作於，依宋元本。</p><h3 id="剝之大壯" tabindex="-1">剝之大壯 <a class="header-anchor" href="#剝之大壯" aria-label="Permalink to “剝之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>夷羿所射，發輒有獲。雙鳧俱得，利以伐國。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>夷羿，即后羿。《左傳襄四年》：&quot;寒浞伯明氏之讒子弟也，伯明氏棄之，夷羿收之，夷羿善射，簒夏&quot;，故雲發輒有獲。震為射，兌為剛魯，故曰夷羿。震為發、為鳧，兌卦數二，故曰雙鳧。震為征伐，坤為國，卦陽長陰消，故曰利以伐國。○以伐，汲古作伐王，茲依宋元本。</p><h3 id="剝之晉" tabindex="-1">剝之晉 <a class="header-anchor" href="#剝之晉" aria-label="Permalink to “剝之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>鳧舞鼓翼，嘉樂堯德。虞夏美功，要荒賓服。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>象多未詳。</p><h3 id="剝之明夷" tabindex="-1">剝之明夷 <a class="header-anchor" href="#剝之明夷" aria-label="Permalink to “剝之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>登邱上山，對酒道歡。終年卒歲，優福無患。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為登、為上、為陵，故曰邱山。坎為酒，震樂震言，故曰道歡。坤為年歲，坎為冬，故曰終年卒歲。坎為患，震為福，故無患。○道，汲古作遇，依宋元本。歡，依汲古，宋元作觀。</p><h3 id="剝之家人" tabindex="-1">剝之家人 <a class="header-anchor" href="#剝之家人" aria-label="Permalink to “剝之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>歲慕花落，陽入陰室。萬物伏匿，藏不可得。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《大有》，惟此詞兼用對象解。</p><h3 id="剝之睽" tabindex="-1">剝之睽 <a class="header-anchor" href="#剝之睽" aria-label="Permalink to “剝之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>螟蟲為賊，害我禾穀。簟瓶空虛，飢無所食。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《節》。</p><h3 id="剝之蹇" tabindex="-1">剝之蹇 <a class="header-anchor" href="#剝之蹇" aria-label="Permalink to “剝之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>陽虎脅主，使德不通。炎離為殃，年穀病傷。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮為虎，納丙，故曰陽虎。震為主，震覆故曰脅主，坎塞故不通，離火故曰炎曰殃。震為年穀，震覆故傷。丁雲：定二年，雉門及兩觀災，正陽虎脅主之時。○使德，宋元本作使得，炎作火，茲依汲古。病，汲古作患，依宋元。</p><h3 id="剝之解" tabindex="-1">剝之解 <a class="header-anchor" href="#剝之解" aria-label="Permalink to “剝之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>四馬共轅，東上泰山。騂驪同力，無有重難，與君笑言。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為馬，卦數四，坎為轅，故曰四馬共轅。震為東為馬，故曰騂驪。震為君、為笑言。○驪，宋元本作驤，依汲古。</p><h3 id="剝之損" tabindex="-1">剝之損 <a class="header-anchor" href="#剝之損" aria-label="Permalink to “剝之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>牧羊稻園，聞虎喧歡。畏懼悚息，終無禍患。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《隨》之《漸》。</p><h3 id="剝之益" tabindex="-1">剝之益 <a class="header-anchor" href="#剝之益" aria-label="Permalink to “剝之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>揚華不時，冬實生危。憂多橫賊，生不能服。昆侖之玉，所求不得。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為華，艮為時，坤履霜為冬，故不時。艮為果實，坤為危憂，巽為盜賊，故曰憂多橫賊。艮為山，震為玉，故曰昆侖之玉。互艮為求，坤喪故所求不得。○所求不得，汲古作取求必得，非，依宋元本。</p><h3 id="剝之夬" tabindex="-1">剝之夬 <a class="header-anchor" href="#剝之夬" aria-label="Permalink to “剝之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>高阜所在，陰氣不臨。洪水不處，為家利寶。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>通《剝》。艮為山，故曰高阜。坤為陰，一陽居眾陰之土，故曰陰氣不臨。坤為水，山高，故曰洪水不處。艮為家、為貝、為金，故曰賓。○臨，汲古作淋，依宋本。</p><h3 id="剝之姤" tabindex="-1">剝之姤 <a class="header-anchor" href="#剝之姤" aria-label="Permalink to “剝之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>釋然遠昝，避患高阜。田獲三狐，以貝為寶。君子所在，安寧不殆。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《謙》。 ○高阜，汲古作革害，依《賁》之《謙》校。</p><h3 id="剝之萃" tabindex="-1">剝之萃 <a class="header-anchor" href="#剝之萃" aria-label="Permalink to “剝之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>兩目失明，日奪無光。脛足跛曳，不可以行。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>頓於邱旁，亡妾莫逐，嵬然獨宿。兌半離，數二，故曰兩目失明，離為日，半離故曰無光。震為脛足，兌半震，故跛不能行。《履》象雲：眇能視，不足以有明，跛能履，不足以有行。林所本也。艮為邱，艮止，故曰頓於邱旁。兌為妾，在外故曰亡妾。震為逐，震覆故曰莫逐。坤為宿，巽為寡，故曰嵬然獨宿。</p><h3 id="剝之升" tabindex="-1">剝之升 <a class="header-anchor" href="#剝之升" aria-label="Permalink to “剝之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>鴻飛遵陸，公歸不復，伯氏客宿。震為鴻，坤為陸，在上故曰鴻飛遵陸。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為公、為歸，坤亡故曰不復。震為伯、為客，坤為宿。首二句《豳風》詩。</p><h3 id="剝之困" tabindex="-1">剝之困 <a class="header-anchor" href="#剝之困" aria-label="Permalink to “剝之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>佩玉累蘃，無以系之。孤怨獨處，愁哀相憂。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>伏震為玉累蘃垂貌。巽為繩、為系，巽為寡，故曰孤獨。坎為憂愁。○累蘃，宋本作累蕊，元本作累蘂，今依汲古。《左傳哀十三年》：&quot;佩玉橤兮餘無所繫之&quot;。</p><h3 id="剝之井" tabindex="-1">剝之井 <a class="header-anchor" href="#剝之井" aria-label="Permalink to “剝之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>載船渡海，雖深何咎。孫子俱在，不失其所。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏震為船，兌為海，坎為深，艮為孫，震為子。○何，宋元本作難，依汲古。</p><h3 id="剝之革" tabindex="-1">剝之革 <a class="header-anchor" href="#剝之革" aria-label="Permalink to “剝之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>鵠求食魚，道遇射弋。繪加我頸，繳縛兩翼。欲飛不能，為羿所得。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為鵠，坤為魚，艮為求，震日故曰食。艮為道路，震為射，巽為弋，弋，系矢射也。為繒繳。艮為頸，震為翼、為飛，艮止故不能飛。坤為惡，故曰羿。○第二句元本作&quot;道過射失&quot;，今依宋本、汲古。兩翼，宋元本作羽翼，依汲古。</p><h3 id="剝之鼎" tabindex="-1">剝之鼎 <a class="header-anchor" href="#剝之鼎" aria-label="Permalink to “剝之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>泥面亂頭，忍恥少羞，日以削消。通《屯》。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>坤為泥，艮為面，坤為亂，坎為首，故曰泥面亂頭。坤為羞恥，坤亡故曰削消。○宋元本下多&quot;兇其自搯&quot;四字，依汲古。頭、消，古音亦協。</p><h3 id="剝之震" tabindex="-1">剝之震 <a class="header-anchor" href="#剝之震" aria-label="Permalink to “剝之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>桑之將落，隕其黃葉。失勢傾倒，如無所立。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《噬嗑》。 ○桑之，元本作葉芳，宋本、汲古本作桑方，今依宋本《履》之《噬嗑》校。</p><h3 id="剝之艮" tabindex="-1">剝之艮 <a class="header-anchor" href="#剝之艮" aria-label="Permalink to “剝之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>巨蛇大鰍，戰於國郊。上下隔塞，主君走逃。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《訟》。 ○主君，宋元本作逐君，依汲古。</p><h3 id="剝之漸" tabindex="-1">剝之漸 <a class="header-anchor" href="#剝之漸" aria-label="Permalink to “剝之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>己動死，連商子。揚砂石，狐狢擾。軍鼓振，吏士苦。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮者，震之反，故曰己動。互坎為棺槨、為死，巽為商賈，伏震為子，艮為砂石，巽風故揚。艮為狐狢，伏震為軍鼓、為士，坎為恐。○狐狢擾，吏士苦，宋元本作&quot;石流狐狢，擾軍鼓振，吏士恐落&quot;，增流字、落字，足成四字句，豈知盡為三字句，惟汲古尚存其真。狐字作胡。</p><h3 id="剝之歸妹" tabindex="-1">剝之歸妹 <a class="header-anchor" href="#剝之歸妹" aria-label="Permalink to “剝之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>張羅搏鳩，兔麗其災。雌雄俱得，為網所賊。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《歸妹》。 ○兔，汲古作烏，賊作滅，依宋元本。</p><h3 id="剝之豐" tabindex="-1">剝之豐 <a class="header-anchor" href="#剝之豐" aria-label="Permalink to “剝之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>三聖相輔，鳥獸喜舞，安樂富有。通《煥》。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>坎為聖，震數三，故曰三聖。艮為鳥、為獸，震為喜舞，巽利三倍故曰富有。○汲古下多&quot;三人諧偶&quot;四字，宋本無，元本為又一林。</p><h3 id="剝之旅" tabindex="-1">剝之旅 <a class="header-anchor" href="#剝之旅" aria-label="Permalink to “剝之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>三奇六耦，相隨俱市。王孫善賈，先得利賓。居止不安，大盜為咎。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>三奇，乾也，六耦，坤也。旅三陽三陰，而一陰隨一陽，二陰隨二陽，故曰相隨。巽為市，艮為王孫、為貝，巽為利，故曰利寶。艮為居止，兌折故不安。巽伏為盜。○安，汲古作移，依宋元本。大盜，宋元本作洪水，依汲古。</p><h3 id="剝之巽" tabindex="-1">剝之巽 <a class="header-anchor" href="#剝之巽" aria-label="Permalink to “剝之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>三人俱行，一人言北。伯仲欲南，少叔不得。中路分道，爭鬬相賊。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通《震》。為人、為行，上下震，二至四覆震故曰三人。震為南，震覆即北，故曰言北。震為伯，互坎為仲，艮為少叔。不得者，言不隨伯仲，獨北行也。震為道路、為爭鬬，坎為賊，全用對象。○一人，宋元本作二人，道爭作爭道，均依汲古。</p><h3 id="剝之兌" tabindex="-1">剝之兌 <a class="header-anchor" href="#剝之兌" aria-label="Permalink to “剝之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>播天舞，光地乳。神所守，樂無咎。言不信誤。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。為天，天舞者，天之樂舞也。《史記趙世家》：&quot;簡子寤曰：餘之帝所，甚樂，與百神遊於鈞天廣樂九奏萬舞，不類三代之樂，其聲動人心&quot;，林詞似指其事。艮為乳，地乳，山也。《洛書甄耀度》：&quot;政山在昆侖東南，為地乳&quot;，王勃《九成宮頌》：&quot;峰橫地乳&quot;。艮為光，互震為舞。《易林》既以陽在上為天，陽在下必為地也，謂震也，震為神、為樂。艮為守，信者宿也。《左傳莊三年》：&quot;一宿為舍，再宿為信&quot;，《詩豳風》：&quot;於女信宿&quot;，《周頌》：&quot;有客信信&quot;，註：四宿也，言不信誤，即言不遲悞也。艮三至上，正反震言，下言如何上，即如言而反，故不宿誤也。○此前四句三字句，第五句四字句，漢魏叢書及俗本皆作四字句，非。光地乳，汲古作地擾亂，守作居，今依宋元本，惟元本無誤字。</p><h3 id="剝之渙" tabindex="-1">剝之渙 <a class="header-anchor" href="#剝之渙" aria-label="Permalink to “剝之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>坐爭立訟，紛紛洶洶。卒成禍亂，災及家公。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮坐震立，三至上正反震言，故曰爭訟。坎為禍災，艮為家，震為公。○洶洶，宋元本作匆匆，依汲古。卒，汲古訛幸，家作我，均依宋元本。</p><h3 id="剝之節" tabindex="-1">剝之節 <a class="header-anchor" href="#剝之節" aria-label="Permalink to “剝之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>蛇行蜿蜒，不能上阪。履節安居，可以無憂。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>伏巽為蛇，艮為阪，震為履，艮為安、為居，坎為憂，震樂故無憂。上坎為陷，故不能上阪。</p><h3 id="剝之中孚" tabindex="-1">剝之中孚 <a class="header-anchor" href="#剝之中孚" aria-label="Permalink to “剝之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>隙大牆壞，蠹眾木折。虎狼為政，天降罪罰。高殺望夷，胡亥以斃。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《大壯》。 ○罰，依《乾》之《大壯》校，各本多作伐。又宋元本無末二句，依汲古。</p><h3 id="剝之小過" tabindex="-1">剝之小過 <a class="header-anchor" href="#剝之小過" aria-label="Permalink to “剝之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>陽不違德，高山多澤。顏子逐兔，未有所得。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為高山，互兌為澤，艮為顏，震為子、為兔、為逐，在外故無得。</p><h3 id="剝之既濟" tabindex="-1">剝之既濟 <a class="header-anchor" href="#剝之既濟" aria-label="Permalink to “剝之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>心多畏惡，時愁日懼。雖有小咎，終無大悔。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>坎為心、為畏、為愁、為懼，離為日。○日，宋元本作自，依汲古。</p><h3 id="剝之未濟" tabindex="-1">剝之未濟 <a class="header-anchor" href="#剝之未濟" aria-label="Permalink to “剝之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>眾神集聚，相與議語。南國虐亂，百姓愁苦。興師征伐，更立賢主。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>半震為神，坎為眾，故曰眾神。坎為集聚，離正反兌口相對，故曰議語。離為南、為虐亂，坎為眾、為憂，故曰百姓愁苦。震為征伐、為主。除坎離外，皆用半象。○興，汲古作舉，更作別，均依宋元本。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
